late-300 px-4 py-3 font-semibold" href="/csi/requests?page=<?= $listing['page'] - 1 ?>">Anterior</a><?php endif; ?><?php if ($listing['page'] < $listing['pages']): ?><a class="rounded-lg border border-slate-300 px-4 py-3 font-semibold" href="/csi/requests?page=<?= $listing['page'] + 1 ?>">Siguiente</a><?php endif; ?></div></nav><?php endif; ?></main></body></html>
